bool XdgAppDatabase::launchTerminalCommand(const std::vector<QString> &cmdline,
                                           const LaunchTerminalCommandOptions &opts) const {
  auto terminal = opts.emulator;

  if (!terminal) {
    if (auto term = terminalEmulator()) { terminal = term.get(); }
  }

  if (!terminal) {
    qWarning() << "No terminal is available to launch the command";
    return false;
  }

  auto xdgApp =
      static_cast<XdgApplication *>(terminal); // NOLINT(cppcoreguidelines-pro-type-static-cast-downcast)

  auto exec = xdgApp->parseExec({}, m_launchPrefix);

  if (exec.empty()) return false;

  QStringList argv;
  std::ranges::for_each(exec | std::views::drop(1), [&](auto &&arg) { argv << arg; });
  auto texec = getTermExec(*xdgApp);

  // per the xdg-terminal-exec spec, a flag ending with '=' takes its value appended
  // to the same argument, without whitespace
  auto addFlag = [&argv](const std::string &flag, const QString &value) {
    if (flag.ends_with('=')) {
      argv << QString::fromStdString(flag) + value;
    } else {
      argv << flag.c_str() << value;
    }
  };

  if (texec.appId && opts.appId) { addFlag(*texec.appId, opts.appId.value()); }
  if (texec.title && opts.title) { addFlag(*texec.title, opts.title.value()); }
  if (texec.dir && opts.workingDirectory) { addFlag(*texec.dir, opts.workingDirectory.value()); }
  if (texec.hold && opts.hold) { argv << texec.hold->c_str(); }

  if (!cmdline.empty()) {
    if (texec.exec) { argv << texec.exec->c_str(); }
    for (const auto &arg : cmdline) {
      argv << arg;
    }
  }

  auto workDir = opts.workingDirectory ? std::optional<std::filesystem::path>(opts.workingDirectory->toStdString())
                                       : xdgApp->data().workingDirectory();
  return launchProcess(exec.front(), argv, workDir, opts.appId.value_or(QString()));
}

